import {waveform} from './scope.mjs';
export function benchSamples(p){return Array.from({length:1024},(_,i)=>benchPoint(i/(1024*p.frequency),p));}
export function benchPoint(t,p){const input=p.on?(p.shape==='dc'?p.offset:waveform(t,{...p,circuit:'direct'})[0]):0;let out=input;if(p.circuit==='divider')out=input*p.r2/(p.r+p.r2);if(p.circuit==='lowpass'||p.circuit==='highpass')out=p.shape==='dc'?(p.circuit==='highpass'?0:input):p.on?waveform(t,p)[1]:0;if(p.fault==='outShort')out=0;if(p.fault==='bypass')out=input;return {in:input,out,gnd:0};}
export function benchReading(p){const a=benchSamples(p).map(s=>s[p.red]-s[p.black]),dc=a.reduce((s,v)=>s+v,0)/a.length;if(p.mode==='dc')return dc;if(p.mode==='ac')return Math.sqrt(a.reduce((s,v)=>s+(v-dc)**2,0)/a.length);if(p.mode==='vpp')return Math.max(...a)-Math.min(...a);if(p.on||p.fault!=='none')return null;if(p.red===p.black)return 0;const pair=[p.red,p.black].sort().join(':');if(p.circuit==='divider')return pair==='in:out'?p.r:pair==='gnd:out'?p.r2:p.r+p.r2;if(p.circuit==='direct')return pair==='in:out'?0:Infinity;if(p.circuit==='lowpass')return pair==='in:out'?p.r:Infinity;return pair==='gnd:out'?p.r:Infinity;}
const defaults={shape:'sine',frequency:1000,vpp:2,offset:2,r:1000,r2:1000,c:100e-9,circuit:'direct',on:true,fault:'none',red:'out',black:'gnd',mode:'dc',time:.2,scale:1,coupling:'dc'};
const experiments=[
 {title:'Media y variación: lo que cada instrumento revela',text:'Conexión directa. Generador: seno, 1 kHz, 2 Vpp, offset +2 V y salida ON. Roja a OUT, negra a GND. Selecciona V DC: predice 2 V; después compara AC RMS y Vpp.',mode:'dc',value:2,circuit:'direct',offset:2},
 {title:'Valor eficaz de una senoide',text:'Conexión directa. Seno de 1 kHz, 2 Vpp y offset 0 V. Roja OUT, negra GND, AC RMS. Predice 0,707 V; observa ±1 V en el osciloscopio.',mode:'ac',value:Math.SQRT1_2,circuit:'direct',offset:0},
 {title:'Divisor: dos caídas, una misma corriente',text:'Divisor. R1 = R2 = 1 kΩ. Generador en continua, offset 5 V y ON. Roja OUT, negra GND, V DC. Predice 2,5 V. Después mide IN respecto a OUT y compara las caídas.',mode:'dc',value:2.5,circuit:'divider',offset:5,shape:'dc'},
 {title:'Encontrar el corte de un RC',text:'RC paso bajo: R = 1 kΩ, C = 100 nF. Seno, 1592 Hz, 2 Vpp, offset 0 V, ON. Roja OUT, negra GND. Mide Vpp: cerca de 1,414 V. CH2 debe retrasarse respecto a CH1.',mode:'vpp',value:Math.SQRT2,circuit:'lowpass',offset:0,frequency:1592},
 {title:'El paso alto elimina la componente continua',text:'RC paso alto: R = 1 kΩ, C = 100 nF. Seno, 1 kHz, 2 Vpp y offset +2 V, ON. Roja OUT, negra GND, V DC. Predice media 0 V en OUT, aunque IN mantiene media 2 V.',mode:'dc',value:0,circuit:'highpass',offset:2}
];
export function benchChallenge(p,n){const e=experiments[n],v=benchReading(p);return p.on&&p.fault==='none'&&p.circuit===e.circuit&&p.shape===(e.shape||'sine')&&p.mode===e.mode&&p.red==='out'&&p.black==='gnd'&&Math.abs(p.offset-e.offset)<.01&&(e.shape==='dc'||Math.abs(p.frequency-(e.frequency||1000))<3)&&(e.shape==='dc'||p.vpp===2)&&(e.circuit==='direct'||p.r===1000)&&(e.circuit!=='divider'||p.r2===1000)&&(!['lowpass','highpass'].includes(e.circuit)||Math.abs(p.c-1e-7)<1e-12)&&v!==null&&Math.abs(v-e.value)<.02;}
export function mountSharedBench({storage}){let p={...defaults},lesson='libre',exercise=0,phase=0,records={};try{records=JSON.parse(storage.getItem('circuitlab-bench-v12')||'{}');if(!records||typeof records!=='object')records={};}catch{}
const el=document.createElement('section');el.id='sharedBench';const home=document.createElement('section');home.id='sharedBenchHome';document.getElementById('coursePage').append(home);home.append(el);
const $=id=>el.querySelector('#'+id);const save=()=>{try{storage.setItem('circuitlab-bench-v12',JSON.stringify(records));}catch{}};
function render(){el.innerHTML=`<div class="sharedHead"><div><span>BANCO INTEGRADO · UN CIRCUITO, TRES INSTRUMENTOS</span><h3>Predice. Mide. Compara.</h3></div><button id="benchFold" aria-expanded="true">Plegar instrumentos</button></div><div id="benchBody"><p class="sharedContext" id="benchContext">Experimento de baja tensión asociado a la lección. Los tres instrumentos leen el mismo modelo ${lesson==='libre'?'de práctica':'de apoyo'}; no simula eléctricamente una placa 3D compleja.</p><label>Práctica guiada<select id="benchExercise">${experiments.map((e,i)=>`<option value="${i}" ${exercise===i?'selected':''}>${i+1}. ${e.title}</option>`).join('')}</select></label><p id="benchTask">${experiments[exercise].text}</p><div class="sharedInstruments"><section class="sharedMeter"><h4>01 · MULTÍMETRO</h4><div id="benchReading" class="sharedLCD" role="status"></div><label>Función<select id="benchMode"><option value="dc">V DC · valor medio</option><option value="ac">V AC · RMS sin continua</option><option value="vpp">Vpp · comparación matemática</option><option value="ohm">Ω · fuente desconectada</option></select></label><div class="sharedPair"><label>Roja<select id="benchRed"><option value="out">OUT</option><option value="in">IN</option><option value="gnd">GND</option></select></label><label>Negra<select id="benchBlack"><option value="gnd">GND</option><option value="in">IN</option><option value="out">OUT</option></select></label></div><small>AC RMS ideal de banda ilimitada. Vpp es una función matemática de comparación; no todos los multímetros la ofrecen.</small></section><section class="sharedGenerator"><h4>02 · GENERADOR</h4><label>Forma<select id="benchShape"><option value="sine">Seno</option><option value="square">Cuadrada 50 %</option><option value="triangle">Triangular</option><option value="dc">Continua</option></select></label><div class="sharedPair"><label>Frecuencia Hz<input id="benchFrequency" type="number" min="1" max="100000" value="${p.frequency}"></label><label>Amplitud Vpp<input id="benchVpp" type="number" min="0.1" max="10" step="0.1" value="${p.vpp}"></label></div><label>Offset / nivel DC (V)<input id="benchOffset" type="number" min="-5" max="5" step="0.1" value="${p.offset}"></label><button id="benchPower">${p.on?'Salida ON · desconectar':'Salida OFF · conectar'}</button></section><section class="sharedScope"><h4>03 · OSCILOSCOPIO · CH1 IN / CH2 OUT</h4><label>Acoplamiento de pantalla<select id="benchCoupling"><option value="dc">DC · nivel completo</option><option value="ac">AC · quitar media solo en pantalla</option></select></label><div id="benchScreen"></div><div class="sharedPair"><label>V/div<select id="benchScale">${[.1,.2,.5,1,2,5].map(x=>`<option value="${x}">${x}</option>`).join('')}</select></label><label>ms/div<input id="benchTime" type="number" min="0.001" max="1000" step="0.01" value="${p.time}"></label></div><p id="benchScopeStatus"></p></section></div><div class="sharedCircuit"><label>Circuito<select id="benchCircuit"><option value="direct">Conexión directa</option><option value="divider">Divisor resistivo</option><option value="lowpass">RC paso bajo</option><option value="highpass">RC paso alto</option></select></label><label>R / R1 (Ω)<input id="benchR" type="number" min="100" max="100000" value="${p.r}"></label><label>R2 del divisor (Ω)<input id="benchR2" type="number" min="100" max="100000" value="${p.r2}"></label><label>C del RC (nF)<input id="benchC" type="number" min="1" max="10000" value="${p.c*1e9}"></label><label>Estado<select id="benchFault"><option value="none">Circuito sano</option><option value="outShort">OUT forzado a GND</option><option value="bypass">Etapa puenteada IN → OUT</option></select></label></div><p id="benchWiring"></p><label>Mi predicción y conclusión<textarea id="benchNotes" rows="3" placeholder="Antes de medir espero… He obtenido… La diferencia indica…"></textarea></label><div class="sharedActions"><button id="benchCheck">Comprobar configuración y lectura</button><button id="benchRecord">Guardar medición en esta lección</button><button id="benchReset">Restaurar valores iniciales</button></div><p id="benchFeedback" role="status"></p><div id="benchLog"></div></div>`;
const maps={benchMode:'mode',benchRed:'red',benchBlack:'black',benchShape:'shape',benchCircuit:'circuit',benchFault:'fault',benchScale:'scale',benchCoupling:'coupling'};for(const [id,key]of Object.entries(maps)){$(id).value=String(p[key]);$(id).onchange=e=>{p[key]=key==='scale'?Number(e.target.value):e.target.value;draw();};}
const nums={benchFrequency:['frequency',1,100000],benchVpp:['vpp',.1,10],benchOffset:['offset',-5,5],benchR:['r',100,100000],benchR2:['r2',100,100000],benchC:['c',1,10000],benchTime:['time',.001,1000]};for(const[id,[key,min,max]]of Object.entries(nums))$(id).oninput=e=>{const n=Number(e.target.value);if(Number.isFinite(n)){p[key]=Math.max(min,Math.min(max,n))*(key==='c'?1e-9:1);draw();}};
$('benchPower').onclick=()=>{p.on=!p.on;$('benchPower').textContent=p.on?'Salida ON · desconectar':'Salida OFF · conectar';draw();};$('benchExercise').onchange=e=>{exercise=Number(e.target.value);$('benchTask').textContent=experiments[exercise].text;$('benchFeedback').textContent='Configura los tres instrumentos siguiendo los pasos. No se cambian los valores automáticamente.';};$('benchFold').onclick=()=>{const hidden=!$('benchBody').hidden;$('benchBody').hidden=hidden;$('benchFold').textContent=hidden?'Mostrar instrumentos':'Plegar instrumentos';$('benchFold').setAttribute('aria-expanded',String(!hidden));};$('benchCheck').onclick=()=>{$('benchFeedback').textContent=benchChallenge(p,exercise)?'✓ Configuración y lectura correctas. Explica la diferencia entre la media y la forma de onda.':'Revisa circuito, valores del generador, función y puntos del multímetro. Sigue la consigna; los tres instrumentos comparten señal.';};$('benchNotes').value=records[lesson]?.note||'';$('benchNotes').oninput=e=>{records[lesson]={...records[lesson],note:e.target.value};save();};$('benchRecord').onclick=()=>{const v=benchReading(p);records[lesson]={...records[lesson],measurements:[...(records[lesson]?.measurements||[]),{time:new Date().toISOString(),params:{...p},reading:Number.isFinite(v)?v:v===null?'no válida':'OL'}].slice(-20)};save();log();};$('benchReset').onclick=()=>{p={...defaults};render();};log();draw();}
function log(){const items=records[lesson]?.measurements||[];$('benchLog').replaceChildren();const h=document.createElement('p');h.textContent=`${items.length} mediciones guardadas en esta lección · este navegador`; $('benchLog').append(h);for(const row of items.slice(-5)){const d=document.createElement('p');d.textContent=`${row.params.red.toUpperCase()} − ${row.params.black.toUpperCase()} · ${row.params.mode.toUpperCase()} · ${typeof row.reading==='number'?row.reading.toFixed(4):row.reading} ${row.params.mode==='ohm'?'Ω':'V'} · ${row.params.circuit} · ${row.params.frequency} Hz`; $('benchLog').append(d);}}
function draw(){const v=benchReading(p);$('benchReading').textContent=v===null?'Retira energía / estado sano para Ω':v===Infinity?'OL':v.toFixed(3)+(p.mode==='ohm'?' Ω':' V');const points=[[],[]],periods=p.time*.01*p.frequency,crowded=periods>10&&p.shape!=='dc';let clip=false;for(let i=0;i<=500&&!crowded;i++){const s=benchPoint(i/500*p.time*.01,p);for(let ch=0;ch<2;ch++){const key=ch?'out':'in',baseline=p.coupling==='ac'?benchPoint(0,{...p,shape:'dc'})[key]:0,y=140-(s[key]-baseline)/p.scale*25;clip ||= y<40||y>240;points[ch].push(`${40+i*1.04},${y}`);}}$('benchScreen').innerHTML=`<svg viewBox="0 0 600 280" aria-label="Osciloscopio del circuito compartido; amarillo entrada, azul salida" role="img"><defs><clipPath id="sharedClip"><rect x="40" y="40" width="520" height="200"/></clipPath></defs><rect width="600" height="280" rx="10" fill="#07171f"/><g stroke="#284650">${Array.from({length:11},(_,i)=>`<path d="M${40+i*52} 40V240"/>`).join('')}${Array.from({length:9},(_,i)=>`<path d="M40 ${40+i*25}H560"/>`).join('')}</g><g clip-path="url(#sharedClip)" fill="none" stroke-width="2"><polyline points="${points[0].join(' ')}" stroke="#ffcc60"/><polyline points="${points[1].join(' ')}" stroke="#61cfff"/></g><g fill="#cee6ef" font-family="monospace" font-size="12"><text x="40" y="24">CH1 IN · CH2 OUT · ${p.scale} V/div · ${p.time} ms/div</text><text x="40" y="264">GND común · ${p.coupling==='ac'?'AC: media eliminada solo en pantalla':'DC: 0 V en eje central'}</text></g></svg>`;$('benchScopeStatus').textContent=crowded?'Demasiados períodos: reduce ms/div para ver hasta 10 períodos.':clip?'Señal fuera de pantalla: aumenta V/div.':'Modelo estacionario ideal. No es adquisición de hardware; las ondas no sinusoidales usan una serie truncada.';$('benchWiring').textContent=(p.circuit==='direct'?'Generador → IN = OUT.':p.circuit==='divider'?'Generador → IN → R1 → OUT → R2 → GND.':p.circuit==='lowpass'?'Generador → IN → R → OUT; C entre OUT y GND.':'Generador → IN → C → OUT; R entre OUT y GND.')+' Todas las referencias del experimento son GND. '+(p.fault==='none'?'':p.fault==='outShort'?'Se fuerza OUT a 0 V; no se calcula corriente de cortocircuito de una fuente real.':'Se modela una etapa puenteada con OUT = IN.');}
function attach(target,id){lesson=id||lesson;if(target.tagName==='DIALOG'){target.classList.add('withBench');if(!target.querySelector('.lessonPane')){const pane=document.createElement('div');pane.className='lessonPane';for(const child of [...target.children])if(child!==el)pane.append(child);target.prepend(pane);const jump=document.createElement('button');jump.className='benchJump';jump.textContent='↓ Medir con los tres instrumentos';jump.onclick=()=>{$('benchBody').hidden=false;$('benchFold').textContent='Plegar instrumentos';$('benchFold').setAttribute('aria-expanded','true');el.scrollIntoView({behavior:'smooth',block:'start'});};pane.prepend(jump);}}if(el.parentElement!==target)target.append(el);$('benchNotes').value=records[lesson]?.note||'';log();}
document.addEventListener('circuitlab:lesson-open',e=>{const t=document.getElementById(e.detail.target);if(t){attach(t,e.detail.id);const first=!!e.detail.beginner;$('benchBody').hidden=first;$('benchFold').textContent=first?'Mostrar instrumentos':'Plegar instrumentos';$('benchFold').setAttribute('aria-expanded',String(!first));$('benchContext').textContent=first?'Primero lee la idea de la lección. Abre los instrumentos cuando el ejercicio indique ajustes concretos. El banco calcula resistencias y RC; no simula bobinas, diodos ni transistores.':'Experimento de baja tensión asociado a la lección. Los tres instrumentos leen el mismo modelo de apoyo; no simula eléctricamente una placa 3D compleja.';}});document.addEventListener('circuitlab:page',e=>{const t=e.detail==='lab'?document.querySelector('#labPage .center'):home;attach(t,lesson);});for(const id of ['planDialog','studyDialog'])document.getElementById(id)?.addEventListener('close',()=>attach(home,lesson));render();return {attach};}
